package com.ecole.gestion_scolaire.hr.entity; import jakarta.persistence.*; import java.time.*; @Entity @Table(name="employee_qualification") public class EmployeeQualification { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="employee_id") private Employee employee; @Column(name="qualification_type",length=50) private String qualificationType; @Column(nullable=false,length=200) private String title; @Column(length=200) private String institution; @Column(length=150) private String specialty; @Column(name="obtained_date") private LocalDate obtainedDate; @Column(columnDefinition="TEXT") private String description;  public Long getId(){return id;} public Employee getEmployee(){return employee;} public void setEmployee(Employee v){employee=v;} public String getQualificationType(){return qualificationType;} public void setQualificationType(String v){qualificationType=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getInstitution(){return institution;} public void setInstitution(String v){institution=v;} public String getSpecialty(){return specialty;} public void setSpecialty(String v){specialty=v;} public LocalDate getObtainedDate(){return obtainedDate;} public void setObtainedDate(LocalDate v){obtainedDate=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} }